/* Minimal vendoring helper for JSZip. This file will try to provide a local JSZip object.
   If you prefer a full bundled minified JSZip, replace this file with the library build.
*/
(function(global){
  // If JSZip is already present (e.g. from a real vendor file), do nothing.
  if (global.JSZip) return;

  // Fallback: dynamically load from CDN to keep functionality while keeping repo small.
  // You can replace this with the full minified JSZip file content if you want true vendoring.
  var cdn = 'https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js';
  var s = document.createElement('script');
  s.src = cdn;
  s.onload = function(){ console.log('Loaded JSZip from CDN fallback'); };
  s.onerror = function(){ console.error('Failed to load JSZip from CDN'); };
  document.head.appendChild(s);
})(window);
